INSERT INTO `chat_messages` VALUES (1,1,'USER','你是谁','TEXT',NULL,'2026-03-26 15:24:09'),(2,1,'ASSISTANT','我是**智教思政平台的AI教学助手**，专门协助教师开展课程思政教学设计。  \n比如我可以帮你做：教学目标设计、思政元素挖掘、案例融入、课堂活动与评价方案设计等。','TEXT',NULL,'2026-03-26 15:24:21'),(14,10,'USER','你是谁','TEXT',NULL,'2026-04-22 14:20:18'),(15,10,'ASSISTANT','我是智能教育思政平台的AI教学助手。当前未检索到可靠的知识库来源，因此先为你提供一般性说明：我可以帮助教师进行思政课程与课程思政教学设计，比如：-设计教学目标-梳理思政元素-生成教学方案与教案-设计课堂活动与案例-制定评价方式-优化课程表达，更简洁实用如果你愿意，我现在就可以帮你做一份教学设计。你只要告诉我：1.课程名称2.授课对象3.课时长度4.想融入的思政主题我就能开始。','TEXT',NULL,'2026-04-22 14:20:26'),(16,10,'USER','今天有什么新闻','TEXT',NULL,'2026-04-22 14:20:39'),(17,10,'ASSISTANT','当前未检索到可靠的知识库来源，我不能直接提供“今天的实时新闻”，以免误导你。不过我可以这样帮你：1.你把新闻链接、标题或截图发给我，我帮你快速总结重点。2.我可以按类别帮你整理“今日新闻关注框架”，如：-国内要闻-国际动态-科技教育-经济金融-社会民生3.如果你需要，我也可以给你一份“今天新闻速览模板”，方便你自己查看后快速整理。例如可用这个模板：-今日最重要的3条新闻：-每条新闻一句话概括：-可能的影响：-值得课堂讨论的思政切入点：如果你愿意，我也可以直接帮你做一个“今日新闻摘要表”。','TEXT',NULL,'2026-04-22 14:20:45');
