INSERT INTO `knowledge_chunks` VALUES (1,'RESOURCE',1,0,'物联网传感器与国家工业安全','传感器作为物联网系统的\"五官\"，是实现万物互联的基石。在工业生产中，高精度的工业级传感器不仅能够实时监测设备的运行状态，确保生产安全，更是实现智能制造转型的关键突破口。','人民日报',NULL,NULL,'物联网传感器与国家工业安全','[\"家国情怀\", \"科技自强\"]','2026-04-19 21:00:49','2026-04-19 21:00:49',0),(2,'RESOURCE',2,0,'人工智能大模型中的伦理边界探讨','大语言模型在极大提高生产力的同时，也带来了版权、隐私以及虚假信息生成的风险。如何在算法设计之初就融入伦理审查机制，是当前AI研究的核心命题。','arXiv (AI Ethics)',NULL,NULL,'人工智能大模型中的伦理边界探讨','[\"职业道德\"]','2026-04-19 21:00:49','2026-04-19 21:00:49',0),(3,'RESOURCE',3,0,'国产自研芯片：从底层架构突破封锁','从底层物理原理的突破到封装工艺的迭代，每一颗国产芯片的诞生都凝聚了科研人员的艰辛努力。我们必须在核心架构上实现完全自主，才能在数字时代掌握话语权。','科技日报',NULL,NULL,'国产自研芯片：从底层架构突破封锁','[\"大国重器\", \"自立自强\"]','2026-04-19 21:00:49','2026-04-19 21:00:49',0),(4,'SUBJECT_KNOWLEDGE',1,0,'CPU设计','研究中央处理器的架构设计，包括控制单元、算术逻辑单元以及指令集的实现。','计算机组成原理',NULL,NULL,'CPU设计',NULL,'2026-04-19 21:00:49','2026-04-19 21:00:49',0),(5,'SUBJECT_KNOWLEDGE',2,0,'指令集','计算机处理器能够识别和执行的指令集合。','计算机组成原理',NULL,NULL,'指令集',NULL,'2026-04-19 21:00:49','2026-04-19 21:00:49',0),(6,'SUBJECT_KNOWLEDGE',3,0,'内存管理','操作系统对内存资源进行分配和管理的机制。','计算机组成原理',NULL,NULL,'内存管理',NULL,'2026-04-19 21:00:49','2026-04-19 21:00:49',0),(7,'SUBJECT_KNOWLEDGE',4,0,'I/O系统','计算机与外部设备进行数据交换的系统。','计算机组成原理',NULL,NULL,'I/O系统',NULL,'2026-04-19 21:00:49','2026-04-19 21:00:49',0),(8,'RESOURCE',4,0,'习近平同莫桑比克总统查波会谈','Summary pending for: 习近平同莫桑比克总统查波会谈','人民网-中国共产党新闻网','https://cpc.people.com.cn/n1/2026/0422/c64094-40706074.html',NULL,'习近平同莫桑比克总统查波会谈','','2026-04-22 10:49:38','2026-04-22 10:49:38',0),(9,'RESOURCE',4,1,'习近平同莫桑比克总统查波会谈','Summary pending for: 习近平同莫桑比克总统查波会谈','人民网-中国共产党新闻网','https://cpc.people.com.cn/n1/2026/0422/c64094-40706074.html',NULL,'习近平同莫桑比克总统查波会谈','[\"工匠精神\",\"责任担当\"]','2026-04-22 10:49:38','2026-04-22 10:49:38',0),(10,'SUBJECT_KNOWLEDGE',5,0,'习近平同莫桑比克总统查波会谈','Summary pending for: 习近平同莫桑比克总统查波会谈','时政资讯','https://cpc.people.com.cn/n1/2026/0422/c64094-40706074.html',NULL,'习近平同莫桑比克总统查波会谈','工匠精神','2026-04-22 10:49:38','2026-04-22 10:49:41',1),(11,'SUBJECT_KNOWLEDGE',5,1,'习近平同莫桑比克总统查波会谈','Summa