  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '任务ID',
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `file_name` varchar(300) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '文件名',
  `file_path` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '文件路径',
  `file_size` bigint DEFAULT NULL COMMENT '文件大小（字节）',
  `status` enum('PENDING','UPLOADING','PARSING','ANALYZING','COMPLETED','FAILED') COLLATE utf8mb4_unicode_ci DEFAULT 'PENDING' COMMENT '任务状态',
  `progress` int DEFAULT '0' COMMENT '处理进度（百分比）',
  `current_step` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '当前处理步骤描述',
  `parsed_content` json DEFAULT NULL COMMENT 'MinerU 解析后的结构化文本',
  `ai_analysis` json DEFAULT NULL COMMENT 'AI 分析结果（思政融合建议）',
  `error_message` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '错误摘要（完整栈走应用日志）',
  `started_at` datetime DEFAULT NULL COMMENT '开始处理时间',
  `completed_at` datetime DEFAULT NULL COMMENT '完成时间',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `course_id` bigint DEFAULT NULL COMMENT 'optional course binding id',
  `gen_doc_title` varchar(300) COLLATE utf8mb4_unicode_ci GENERATED ALWAYS AS (json_unquote(json_extract(`parsed_content`,_gbk'$.title'))) VIRTUAL,
  PRIMARY KEY (`id`),
  KEY `idx_user` (`user_id`),
  KEY `idx_status` (`status`),
  KEY `idx_created_at` (`created_at`),
  KEY `idx_gen_doc_title` (`gen_doc_title`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='文档解析任务表';
