INSERT INTO `parse_tasks` (`id`, `user_id`, `file_name`, `file_path`, `file_size`, `status`, `progress`, `current_step`, `parsed_content`, `ai_analysis`, `error_message`, `started_at`, `completed_at`, `created_at`, `updated_at`, `course_id`) VALUES (3,3,'02-进阶架构与源站高可用.docx','E:\\study\\smart-education-ideology\\backend\\uploads\\8bdc1ffc-1725-4840-b4d2-81f71dac56a6.docx',50509,'FAILED',80,'Pipeline failed','{\"title\": \"Fallback Document\", \"overview\": \"Document structure parser fallback result.\", \"documentType\": \"UNKNOWN\", \"teachingFocus\": [\"Please retry pipeline regeneration after provider recovery.\"], \"chapterOutline\": [\"Chapter extraction pending\"]}','{\"inferred\": true, \"warnings\": [\"document-structure attempt 1 failed: All configured AI providers failed: openai: chat.completions: AI service call failed: 500 - Post \\\"https://chatgpt.com/backend-api/codex/responses\\\": EOF\", \"document-structure attempt 2 failed: All configured AI providers failed: openai: chat.completions: AI service call failed: 500 - Post \\\"https://chatgpt.com/backend-api/codex/responses\\\": EOF\", \"document-structure fallback used.\", \"teaching-artifact-generation attempt 1 failed: Cannot deserialize value of type `java.lang.String` from Object value (token `JsonToken.START_OBJECT`)\\n at [Source: UNKNOWN; byte offset: #UNKNOWN] (through reference chain: com.smartedu.dto.TeachingArtifactsDto[\\\"lectureNotes\\\"])\", \"teaching-artifact-generation attempt 2 failed: Cannot deserialize value of type `java.lang.String` from Array value (token `JsonToken.START_ARRAY`)\\n at [Source: UNKNOWN; byte offset: #UNKNOWN] (through reference chain: com.smartedu.dto.TeachingArtifactsDto[\\\"lectureNotes\\\"])\", \"teaching-artifact-generation fallback used.\"], \"schemaVersion\": \"v1\", \"ideologyMatches\": [{\"confidence\": 94, \"matchReason\": \"强调在流量激增和复杂请求场景下先守住源站稳定与业务连续性，体现风险预判和安全兜底意识。\", \"ideologyElement\": \"底线思维\", \"knowledgePointName\": \"CDN第二层的核心目标是守护源站高可用\"}, {\"confidence\": 95, \"matchReason\": \"根据静态与动态请求的不同特征采取差异化策略，体现从实际出发进行分类施策的方法。\", \"ideologyElement\": \"具体问题具体分析\", \"knowledgePointName\": \"静态与动态请求需要区别治理\"}, {\"confidence\": 91, \"matchReason\": \"该机制兼顾响应速度、用户体验与数据更新，在局部延迟和整体效率之间进行协同优化。\", \"ideologyElement\": \"系统观念\", \"knowledgePointName\": \"stale-while-revalidate允许陈旧内容先返回再后台刷新\"}, {\"confidence\": 96, \"matchReason\": \"明确区分可容忍短时陈旧与强一致数据的适用边界，体现按业务真实需求选择技术方案。\", \"ideologyElement\": \"实事求是\", \"knowledgePointName\": \"stale-while-revalidate适用于可容忍短时陈旧的高频内容\"}, {\"confidence\": 95, \"matchReason\": \"通过空值缓存、参数校验和布隆过滤器等手段预防无效请求冲击后端，体现主动识别并防控风险。\", \"ideologyElement\": \"风险意识\", \"knowledgePointName\": \"缓存穿透是请求不存在的数据直达后端\"}, {\"confidence\": 94, \"matchReason\": \"针对热点失效瞬间的并发风险提前设计预热、互斥和逻辑过期等机制，体现居安思危。\", \"ideologyElement\": \"忧患意识\", \"knowledgePointName\": \"缓存击穿是热点数据失效导致并发回源\"}, {\"confidence\": 97, \"matchReason\": \"通过随机抖动、多级缓存和限流降级避免系统性冲击，体现守住系统稳定底线的思想。\", \"ideologyElement\": \"底线思维\", \"knowledgePointName\": \"缓存雪崩是大量缓存同时失效引发回源洪峰\"}, {\"confidence\": 92, \"matchReason\": \"同时关注版本一致性与首访性能，在更新治理和容量准备之间进行协同安排。\", \"ideologyElement\": \"统筹兼顾\", \"knowledgePointName\": \"缓存刷新与预热分别解决旧内容清理和冷启动问题\"}, {\"confidence\": 97, \"matchReason\": \"强调按URL、目录、后缀或标签进行细粒度治理，避免简单粗放操作带来连锁风险。\", \"ideologyElement\": \"精准施策\", \"knowledgePointName\": \"精准刷新优于全站清缓存\"}, {\"confidence\": 95, \"matchReason\": \"在业务高峰前主动完成热点资源准备，减少突发流量对源站的冲击，体现事前防范。\", \"ideologyElement\": \"预防为主\", \"knowledgePointName\": \"缓存预热可平滑活动开始时的回源峰值\"}, {\"confidence\": 90, \"matchReason\": \"通过路径、协议和传输优化提升动态请求性能，体现以技术创新解决复杂场景问题。\", \"ideologyElement\": \"创新意识\", \"knowledgePointName\": \"动态网络加速依赖路径与传输优化而非缓存\"}, {\"confidence\": 93, \"matchReason\": \"通过域名拆分、规则隔离和链路追踪实现精细化运维，体现分层分类治理思路。\", \"ideologyElement\": \"系统治理\", \"knowledgePointName\": \"动态域名应与静态资源域名拆分治理\"}], \"knowledgePoints\": [{\"chapter\": \"第二层：进阶架构与源站高可用\", \"pointName\": \"CDN第二层的核心目标是守护源站高可用\", \"definition\": \"当流量增大、热点集中、动态请求增多时，CDN不仅用于加速，还承担削峰、缓存治理、回源控制、动态优化和可观测入口等职责，以避免源站被压垮。\", \"importance\": \"HIGH\", \"evidenceSnippet\": \"CDN不只是加速器，更像一个：流量削峰层、缓存治理层、回源控制层、动态请求优化层、可观测性入口层\"}, {\"chapter\": \"1.为什么“加速”会变成“守护源站”\", \"pointName\": \"静态与动态请求需要区别治理\", \"definition\": \"静态请求适合缓存，动态请求通常不能缓存但要求低延迟透传，因此高可用架构必须按请求类型采用不同策略。\", \"importance\": \"HIGH\", \"evidenceSnippet\": \"静态请求…商品图片、JS/CSS…；动态请求…登录、查库存、下订单\"}, {\"chapter\": \"2.1stale-while-revalidate\", \"pointName\": \"stale-while-revalidate允许陈旧内容先返回再后台刷新\", \"definition\": \"缓存对象过期后，在允许的窗口内可先返回旧内容，同时异步向上级节点或源站拉取新版本，从而兼顾响应速度与更新能力。\", \"importance\": \"HIGH\", \"evidenceSnippet\": \"允许缓存对象在变成stale后，先返回旧内容，再触发后台刷新\"}, {\"chapter\": \"2.1stale-while-revalidate\", \"pointName\": \"stale-while-revalidate适用于可容忍短时陈旧的高频内容\", \"definition\": \"该策略适合高频访问、无需秒级强一致的页面，如商品列表页；不适合库存、价格等强一致要求高的数据。\", \"importance\": \"HIGH\", \"evidenceSnippet\": \"高频访问的列表页…更新不是秒级强一致的内容…坑1：把有强一致要求的数据也做了陈旧返回\"}, {\"chapter\": \"2.2缓存穿透、击穿、雪崩\", \"pointName\": \"缓存穿透是请求不存在的数据直达后端\", \"definition\": \"当请求目标根本不存在时，缓存无法命中，请求会持续打到数据库或源站，需要用空值缓存、参数校验和布隆过滤器等手段防护。\", \"importance\": \"HIGH\", \"evidenceSnippet\": \"穿透：查的是根本不存在的数据…防法：对不存在结果做短TTL空值缓存、参数合法性校验、布隆过滤器\"}, {\"chapter\": \"2.2缓存穿透、击穿、雪崩\", \"pointName\": \"缓存击穿是热点数据失效导致并发回源\", \"definition\": \"某个热点对象在失效瞬间遭遇大量并发访问，多个请求同时回源，需通过热点预热、互斥锁、逻辑过期或stale-while-revalidate抑制。\", \"importance\": \"HIGH\", \"evidenceSnippet\": \"击穿：某个热点数据刚好失效，大量请求同时打后端\"}, {\"chapter\": \"2.2缓存穿透、击穿、雪崩\", \"pointName\": \"缓存雪崩是大量缓存同时失效引发回源洪峰\", \"definition\": \"当一批缓存设置了相同过期时间并在高峰集中失效时，会造成源站和数据库被同时冲击，应采用TTL随机抖动、多级缓存、限流降级等手段。\", \"importance\": \"HIGH\", \"evidenceSnippet\": \"雪崩：大量缓存同时失效，像闸门一起打开…防法：TTL加随机抖动、分批发布与预热、多级缓存、限流与降级\"}, {\"chapter\": \"2.3精准缓存刷新与预热（Purge&Prefetch）\", \"pointName\": \"缓存刷新与预热分别解决旧内容清理和冷启动问题\", \"definition\": \"Purge用于快速剔除旧缓存，Prefetch用于提前将热点内容加载进缓存体系，以避免版本不一致和首访回源成本。\", \"importance\": \"HIGH\", \"evidenceSnippet\": \"缓存刷新是把旧内容从缓存体系里剔除，缓存预热是提前把即将被访问的内容放进缓存体系\"}, {\"chapter\": \"2.3精准缓存刷新与预热（Purge&Prefetch）\", \"pointName\": \"精准刷新优于全站清缓存\", \"definition\": \"应按URL、目录、后缀或标签进行细粒度刷新，避免全站清缓存导致命中率骤降和源站回源雪崩。\", \"importance\": \"HIGH\", \"evidenceSnippet\": \"不做全站大面积清缓存，避免瞬时雪崩…为什么活动前不建议做“全站一键清缓存”\"}, {\"chapter\": \"2.3精准缓存刷新与预热（Purge&Prefetch）\", \"pointName\": \"缓存预热可平滑活动开始时的回源峰值\", \"definition\": \"通过提前生成热点资源清单并执行预热，可减少冷缓存带来的首访回源和活动开始瞬间的源站压力。\", \"importance\": \"MEDIUM\", \"evidenceSnippet\": \"在活动开始前访问一次关键资源触发缓存生成…降低活动开始瞬间的回源洪峰\"}, {\"chapter\": \"3.1为什么动态请求也能加速\", \"pointName\": \"动态网络加速依赖路径与传输优化而非缓存\", \"definition\": \"DCDN主要通过最近边缘接入、骨干网优选路径、BGPAnycast、TCP优化和拥塞控制等方式，加速动态请求到源站的传输。\", \"importance\": \"HIGH\", \"evidenceSnippet\": \"动态加速不是靠缓存命中，而是靠优化请求在网络中的路径、协议与传输方式\"}, {\"chapter\": \"3.1为什么动态请求也能加速\", \"pointName\": \"动态域名应与静态资源域名拆分治理\", \"definition\": \"高频API应单独启用动态加速并保留链路追踪ID，以便隔离缓存规则、避免误缓存动态响应并定位边缘到源站的抖动。\", \"importance\": \"MEDIUM\", \"evidenceSnippet\": \"高频动态接口建议：与静态资源域名拆分；针对API域名单独启用动态加速；保留链路追踪ID\"}], \"documentStructure\": {\"title\": \"Fallback Document\", \"overview\": \"Document structure parser fallback result.\", \"documentType\": \"UNKNOWN\", \"teachingFocus\": [\"Please retry pipeline regeneration after provider recovery.\"], \"chapterOutline\": [\"Chapter extraction pending\"]}, \"teachingArtifacts\": {\"cases\": [\"Case generation is pending due to provider fallback.\"], \"questions\": [{\"stem\": \"Explain the key concept and its ideology relevance.\", \"scoringPoints\": [\"Concept accuracy\", \"Ideology relevance\", \"Teaching expression\"], \"referenceAnswer\": \"Reference answer pending provider recovery.\"}], \"lectureNotes\": \"Teaching artifact generation fallback result.\"}}','Manually cleared: pipeline JSON exceeded TEXT limit before schema fix.','2026-04-22 20:26:08',NULL,'2026-04-22 20:26:08','2026-04-22 20:47:09',NULL),(4,3,'02-进阶架构与源站高可用.docx','E:\\study\\smart-education-ideology\\backend\\uploads\\50e556d8-1610-43a4-a60a-45cea41e82a4.docx',50509,'COMPLETED',100,'Completed','{\"title\": \"第二层：进阶架构与源站高可用（守护后端命脉）\", \"overview\": \"本文围绕CDN在高流量场景下如何从“加速用户访问”转向“守护源站稳定”展开，重点讲解高级缓存控制、缓存穿透/击穿/雪崩防护、精准缓存刷新与预热，以及动态网络加速