DROP TABLE IF EXISTS `resources`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `resources` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '资源ID',
  `title` varchar(300) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '资源标题',
  `source` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源出处',
  `source_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源链接（用于去重与追溯）',
  `category` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '学科分类',
  `content` text COLLATE utf8mb4_unicode_ci COMMENT '知识点原文内容',
  `ideology_summary` text COLLATE utf8mb4_unicode_ci COMMENT 'LLM提取的思政价值总结',
  `tags` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '思政标签（JSON数组）',
  `file_path` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '文件存储路径',
  `file_type` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '文件类型',
  `file_size` bigint DEFAULT NULL COMMENT '文件大小（字节）',
  `sync_status` enum('PENDING','PROCESSING','SYNCED','FAILED') COLLATE utf8mb4_unicode_ci DEFAULT 'PENDING' COMMENT '同步状态',
  `parse_task_id` bigint DEFAULT NULL COMMENT '关联的解析任务ID',
  `creator_id` bigint DEFAULT NULL COMMENT '创建者ID',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_source_url` (`source_url`),
  KEY `idx_category` (`category`),
  KEY `idx_sync_status` (`sync_status`),
  KEY `idx_creator` (`creator_id`),
  FULLTEXT KEY `ft_search` (`title`,`content`,`ideology_summary`)
) ENGINE=InnoDB AUTO_INCREMENT=35 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='资源表';
/*!40101 SET character_set_client = @saved_cs_client */;

