DROP TABLE IF EXISTS `student_activities`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `student_activities` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '记录ID',
  `student_id` bigint NOT NULL COMMENT '学生用户ID',
  `course_id` bigint DEFAULT NULL COMMENT '课程ID',
  `knowledge_point_id` bigint DEFAULT NULL COMMENT '知识点ID',
  `study_duration` int DEFAULT '0' COMMENT '学习时长（分钟）',
  `correct_rate` decimal(5,2) DEFAULT '0.00' COMMENT '答题正确率（百分比）',
  `focus_score` decimal(5,2) DEFAULT '0.00' COMMENT '专注度评分（0-100）',
  `emotion_status` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '情绪状态：NORMAL/CONFUSED/ANGRY/DISTRACTED',
  `alert_level` tinyint DEFAULT '0' COMMENT '预警等级：0-正常 1-轻度 2-中度 3-重度',
  `alert_message` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预警消息',
  `session_start` datetime DEFAULT NULL COMMENT '学习会话开始时间',
  `session_end` datetime DEFAULT NULL COMMENT '学习会话结束时间',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_student` (`student_id`),
  KEY `idx_course` (`course_id`),
  KEY `idx_alert_level` (`alert_level`),
  KEY `idx_created_at` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='学习行为表';
/*!40101 SET character_set_client = @saved_cs_client */;

