INSERT INTO `subject_ideology_matches` VALUES (1,1,1,1,95.00,'在CPU设计的精细调试过程中，引导学生体悟\"失之毫厘谬以千里\"的严谨态度，通过底层架构国产化进程强化使命感。','2026-03-26 14:16:05','2026-04-19 21:00:40'),(3,5,4,1,95.00,'内容突出维护国家核心利益、深化中莫和中非友好合作，体现服务国家发展与国际交往的家国情怀；强调在联合国等多边机制中加强协调、团结协作、共促和平发展，契合协同共治；提出共同应对国际挑战、捍卫国际公平正义，体现责任担当；强调维护联合国宪章宗旨原则和国际关系基本准则，体现依法治理。','2026-04-22 10:49:38','2026-04-22 14:24:10'),(5,6,4,1,95.00,'声明强调坚定维护国家主权、安全和发展利益，体现家国情怀；提出落实全球发展倡议、深化中非合作、推动共同发展，体现责任担当；倡导共商共建共享、加强双边及多边协调合作，体现协同共治；重申一个中国原则、维护联合国大会第2758号决议权威，并以框架协定提供制度保障，体现依法治理；推动产业链升级、工业化、农业和能源矿产合作，体现产业创新；重视地质科技创新、教育培训和技术合作服务国家发展，体现科技报国。','2026-04-22 10:49:39','2026-04-22 14:24:19'),(7,7,4,1,95.00,'内容突出国家间友好往来、维护社会主义事业和推动中老命运共同体建设，体现从国家发展与对外关系大局出发的家国情怀；同时强调双方密切协调配合、深化战略对接、携手应对共同挑战，符合协同共治的价值导向。','2026-04-22 10:49:41','2026-04-22 14:24:24'),(9,8,4,0,80.00,'内容明确表述驻外大使任免是“根据全国人民代表大会常务委员会的决定”进行，体现国家机构依照法定程序开展外交人事工作，符合“依法治理”。同时，驻外大使承担国家对外交往与利益维护职责，相关任免反映外交岗位的职责承接与使命落实，体现“责任担当”。','2026-04-22 10:50:03','2026-04-22 14:24:31'),(26,17,4,1,95.00,'内容突出坚定支持彼此核心利益、国家统一和重大关切，体现维护国家利益与友好互信的家国情怀；强调维护公平正义、捍卫共同利益、服务两国现代化建设，体现责任担当；提出加强中莫、中非团结协作，落实全球倡议、推动构建人类命运共同体，体现协同共治。','2026-04-22 14:21:56','2026-04-22 14:21:55'),(27,17,9,0,80.00,'内容突出坚定支持彼此核心利益、国家统一和重大关切，体现维护国家利益与友好互信的家国情怀；强调维护公平正义、捍卫共同利益、服务两国现代化建设，体现责任担当；提出加强中莫、中非团结协作，落实全球倡议、推动构建人类命运共同体，体现协同共治。','2026-04-22 14:21:56','2026-04-22 14:21:55'),(28,18,7,1,95.00,'内容突出立法机构交流、法治建设经验分享，直接体现依法治理；同时强调相互尊重、合作共赢、维护多边主义和深化双边及中非、中欧合作，体现协同共治。','2026-04-22 14:22:03','2026-04-22 14:22:02'),(29,18,9,0,80.00,'内容突出立法机构交流、法治建设经验分享，直接体现依法治理；同时强调相互尊重、合作共赢、维护多边主义和深化双边及中非、中欧合作，体现协同共治。','2026-04-22 14:22:03','2026-04-22 14:22:02'),(30,19,4,1,95.00,'内容突出维护国家主权、推进中国式现代化和对外开放，体现家国情怀；强调面对全球挑战共同维护和平稳定，体现责任担当；多次提出维护以联合国为核心的国际体系和以国际法为基础的国际秩序，符合依法治理；倡导中西及中欧加强沟通协作、坚持多边主义，体现协同共治；提出加强贸易、新能源、智能经济等领域合作，体现产业创新。','2026-04-22 14:22:10','2026-04-22 14:22:10'),(31,19,7,0,80.00,'内容突出维护国家主权、推进中国式现代化和对外开放，体现家国情怀；强调面对全球挑战共同维护和平稳定，体现责任担当；多次提出维护以联合国为核心的国际体系和以国际法为基础的国际秩序，符合依法治理；倡导中西及中欧加强沟通协作、坚持多边主义，体现协同共治；提出加强贸易、新能源、智能经济等领域合作，体现产业创新。','2026-04-22 14