--
-- Table structure for table `subject_knowledge`
--

DROP TABLE IF EXISTS `subject_knowledge`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `subject_knowledge` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '学科知识ID',
  `name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '学科知识名称',
  `subject` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '所属学科',
  `category` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '分类',
  `summary` text COLLATE utf8mb4_unicode_ci COMMENT '学科知识浓缩摘要',
  `ideology_summary` text COLLATE utf8mb4_unicode_ci COMMENT '思政匹配理由摘要',
  `source_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源链接',
  `position_x` double DEFAULT '0' COMMENT '图谱中X坐标',
  `position_y` double DEFAULT '0' COMMENT '图谱中Y坐标',
  `node_size` enum('LG','MD','SM') COLLATE utf8mb4_unicode_ci DEFAULT 'MD' COMMENT '节点大小',
  `icon` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '节点图标',
  `tag` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '节点标签',
  `sub_title` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '副标题',
  `creator_id` bigint DEFAULT NULL COMMENT '创建者ID',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  KEY `idx_subject_name` (`name`),
  KEY `idx_subject_subject` (`subject`),
  KEY `idx_subject_category` (`category`),
  KEY `idx_subject_creator` (`creator_id`)
) ENGINE=InnoDB AUTO_INCREMENT=23 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='学科知识表';
