CREATE TABLE `subject_knowledge_sources` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '来源ID',
  `subject_knowledge_id` bigint NOT NULL COMMENT '学科知识ID',
  `resource_id` bigint NOT NULL COMMENT '资源ID',
  `source_type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源类型：CRAWLED_RESOURCE/UPLOADED_DOCUMENT',
  `source_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源链接',
  `excerpt` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源摘录',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_subject_resource` (`subject_knowledge_id`,`resource_id`),
  KEY `idx_sks_subject_id` (`subject_knowledge_id`),
  KEY `idx_sks_resource_id` (`resource_id`)
) ENGINE=InnoDB AUTO_INCREMENT=33 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='学科知识来源追溯表';
