INSERT INTO `subject_knowledge_sources` VALUES (1,1,3,'CRAWLED_RESOURCE','https://example.com/resource/chip','国产芯片的自主突破体现了底层架构设计的重要性。','2026-03-26 14:16:05','2026-03-26 14:16:05'),(2,5,4,'CRAWLED_RESOURCE','https://cpc.people.com.cn/n1/2026/0422/c64094-40706074.html','Summary pending for: 习近平同莫桑比克总统查波会谈','2026-04-22 10:49:38','2026-04-22 10:49:38'),(3,6,5,'CRAWLED_RESOURCE','https://cpc.people.com.cn/n1/2026/0422/c64387-40706092.html','Summary pending for: 中华人民共和国和莫桑比克共和国关于构建新时代中莫命运共同体的联合声明','2026-04-22 10:49:39','2026-04-22 10:49:39'),(4,5,6,'CRAWLED_RESOURCE','http://jhsjk.people.cn/article/40706074?isindex=1','Summary pending for: 习近平同莫桑比克总统查波会谈','2026-04-22 10:49:41','2026-04-22 10:49:41'),(5,7,7,'CRAWLED_RESOURCE','http://jhsjk.people.cn/article/40706076?isindex=1','Summary pending for: 习近平会见老挝人民革命党中央总书记、国家主席特使沙伦赛','2026-04-22 10:49:41','2026-04-22 10:49:41'),(6,5,8,'CRAWLED_RESOURCE','https://cpc.people.com.cn/n1/2026/0422/c435113-40706120.html','Summary pending for: 习近平同莫桑比克总统查波会谈','2026-04-22 10:50:03','2026-04-22 10:50:03'),(7,7,9,'CRAWLED_RESOURCE','https://cpc.people.com.cn/n1/2026/0422/c435113-40706119.html','Summary pending for: 习近平会见老挝人民革命党中央总书记、国家主席特使沙伦赛','2026-04-22 10:50:03','2026-04-22 10:50:03'),(8,8,10,'CRAWLED_RESOURCE','http://jhsjk.people.cn/article/40706078?isindex=1','Summary pending for: 国家主席习近平任免驻外大使','2026-04-22 10:50:03','2026-04-22 10:50:03'),(18,7,20,'CRAWLED_RESOURCE','https://cpc.people.com.cn/n1/2026/0422/c64094-40706076.html','Summary pending for: 习近平会见老挝人民革命党中央总书记、国家主席特使沙伦赛','2026-04-22 10:58:29','2026-04-22 10:58:29'),(19,8,21,'CRAWLED_RESOURCE','https://cpc.people.com.cn/n1/2026/0422/c64094-40706078.html','Summary pending for: 国家主席习近平任免驻外大使','2026-04-22 10:58:29','2026-04-22 10:58:29'),(22,17,24,'CRAWLED_RESOURCE','https://cpc.people.com.cn/n1/2026/0422/c64094-40706073.html','内容突出坚定支持彼此核心利益、国家统一和重大关切，体现维护国家利益与友好互信的家国情怀；强调维护公平正义、捍卫共同利益、服务两国现代化建设，体现责任担当；提出加强中莫、中非团结协作，落实全球倡议、推动构建人类命运共同体，体现协同共治。','2026-04-22 14:21:56','2026-04-22 14:21:56'),(23,18,25,'CRAWLED_RESOURCE','https://cpc.people.com.cn/n1/2026/0422/c64094-40706075.html','内容突出立法机构交流、法治建设经验分享，直接体现依法治理；同时强调相互尊重、合作共赢、维护多边主义和深化双边及中非、中欧合作，体现协同共治。','2026-04-22 14:22:03','2026-04-22 14:22:03'),(24,19,26,'CRAWLED_RESOURCE','http://jhsjk.people.cn/article/40701534?isindex=1','内容突出维护国家主权、推进中国式现代化和对外开放，体现家国情怀；强调面对全球挑战共同维护和平稳定，体现责任担当；多次提出维护以联合国为核心的国际体系和以国际法为基础的国际秩序，符合依法治理；倡导中西及中欧加强沟通协作、坚持多边主义，体现协同共治；提出加强贸易、新能源、智能经济等领域合作，体现产业创新。','2026-04-22 14:22:10','2026-04-22 14:22:10'),(25,20,27,'CRAWLED_RESOURCE','http://jhsjk.people.cn/article/40701532?isindex=1','内容突出中国在地区热点问题上劝和促谈、维护和平稳定的建设性作用，体现责任担当；强调维护以联合国为核心的国际体系和以国际法为基础的国际秩序，契合依法治理；倡导在联合国、金砖等多边平台加强协调合作，推动共同安全与共同发展，体现协同共治。','2026-04-22 14:22:19','2026-04-22 14:22:19'),(26,5,28,'CRAWLED_RESOURCE','https://cpc.people.com.cn/n1/2026/0422/c64094-40706074.html','内容突出维护国家核心利益、深化中莫和中非友好合作，体现服务国家发展与国际交往的家国情怀；强调在联合国等多边机制中加强协调、团结协作、共促和平发展，契合协同共治；提出共同应对国际挑战、捍卫国际公平正义，体现责任担当；强调维护联合国宪章宗旨原则和国际关系基本准则，体现依法治理。','2026-04-22 14:24:10','2026-04-22 14:24:10'),(27,6,29,'CRAWLED_RESOURCE','https://cpc.people.com.cn/n1/2026/0422/c64387-40706092.html','声明强调坚定维护国家主权、安全和发展利益，体现家国情怀；提出落实全球发展倡议、深化中非合作、推动共同发展，体现责任担当；倡导共商共建共享、加强双边及多边协调合作，体现协同共治；重申一个中国原则、维护联合国大会第2758号决议权威，并以框架协定提供制度保障，体现依法治理；推动产业链升级、工业化、农业和能源矿产合作，体现产业创新；重视地质科技创新、教育培训和技术合作服务国家发展，体现科技报国。','2026-04-22 14:24:19','2026-04-22 14:24:19'),(28,7,30,'CRAWLED_RESOURCE','http://jhsjk.people.cn/article/40706076?isindex=1','内容突出国家间友好往来、维护社会主义事业和推动中老命运共同体建设，体现从国家发展与对外关系大局出发的家国情怀；同时强调双方密切协调配合、深化战略对接、携手应对共同挑战，符合协同共治的价值导向。','2026-04-22 14:24:25','2026-04-22 14:24:25'),(29,8,31,'CRAWLED_RESOURCE','http://jhsjk.people.cn/article/40706078?isindex=1','内容明确表述驻外大使任免是“根据全国人民代表大会常务委员会的决定”进行，体现国家机构依照法定程序开展外交人事工作，符合“依法治理”。同时，驻外大使承担国家对外交往与利益维护职责，相关任免反映外交岗位的职责承接与使命落实，体现“责任担当”。','2026-04-22 14:24:31','2026-04-22 14:24:31'),(30,21,32,'UPLOADED_DOCUMENT','upload://parse-task/1','Pending Knowledge Point -> Craftsmanship Spirit: Fallback ideology mapping due to provider instability.','2026-04-22 17:33:14','2026-04-22 17:33:14'),(31,21,33,'UPLOADED_DOCUMENT','upload://parse-task/2','数字技术赋能高校精准思政的研究主题 -> 立德树人: 知识点聚焦以数字技术提升高校思想政治教育的针对性和实效性，直接服务高校立德树人根本任务。\n数字技术赋能高校精准思政的研究主题 -> 教育数字化: 人工智能、区块链、物联网等技术进入思政教育场景，体现教育数字化转型要求。\n数字技术赋能高校精准思政的研究主题 -> 科技赋能育人: 强调以数字技术提升识别、供给和评估能力，体现技术服务育人目标的导向。\n精准思政的政策背景 -> 政策导向: 知识点直接依据教育部推进精准思政的战略部署展开，政策指向明确。\n精准思政的政策背景 -> 立德树人: 精准思政政策背景的核心目的是提升思政工作的实效，服务立德树人。\n精准思政的政策背景 -> 教育强国: 思政精准化是提升高等教育治理和人才培养质量的重要组成，契合教育强国建设。\n数字技术的教育变革效应 -> 教育数字化: 知识点强调数字技术重构传播、教学和评价方式，属于教育数字化的典型内容。\n数字技术的教育变革效应 -> 创新发展: 教育生态向智能化、个性化、泛在化发展，体现以创新驱动教育改革。\n数字技术的教育变革效应 -> 科技强国: 数字技术推动教育现','2026-04-22 19:36:31','2026-04-22 19:36:31'),(32,22,34,'UPLOADED_DOCUMENT','upload://parse-task/4','CDN在高流量下的源站保护角色 -> 责任担当: 强调在高流量场景下通过削峰、回源控制和可观测性守护系统稳定，体现面向关键基础设施的工程责任。\nCDN在高流量下的源站保护角色 -> 系统观念: 将CDN定位为流量削峰层、缓存治理层和观测入口层，体现从整体链路统筹稳定性的系统思维。\n静态请求与动态请求的治理差异 -> 实事求是: 根据静态与动态请求的不同特征采取差异化治理方案，体现从实际问题出发选择技术路径。\n静态请求与动态请求的治理差异 -> 精准施策: 区分缓存减压与链路优化两类手段，反映面向具体业务场景进行精细化治理的意识。\nstale-while-revalidate语义 -> 效率意识: 通过先返回旧内容再后台刷新，平衡响应速度与更新效率，体现对服务效率的重视。\nstale-while-revalidate语义 -> 辩证思维: 该机制兼顾性能与更新能力，体现对速度与一致性关系的平衡把握。\nstale-while-revalidate的时间窗口理解 -> 严谨规范: 准确区分max-age与stale-while-revalidate的时间边界，体现遵循技术规范和精确认知的要求','2026-04-22 20:51:54','2026-04-22 20:51:54');
