DROP TABLE IF EXISTS `system_activities`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `system_activities` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '动态ID',
  `user_id` bigint DEFAULT NULL COMMENT '关联用户ID',
  `activity_type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '动态类型：AI_ANALYSIS/UPLOAD/ALERT/GRAPH_UPDATE',
  `title` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '动态标题',
  `description` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '动态描述',
  `icon` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '图标名称',
  `reference_id` bigint DEFAULT NULL COMMENT '关联对象ID',
  `reference_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关联对象类型',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_user` (`user_id`),
  KEY `idx_type` (`activity_type`),
  KEY `idx_created_at` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='系统动态表';
