DROP TABLE IF EXISTS `teaching_material_traces`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `teaching_material_traces` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'trace id',
  `material_id` bigint NOT NULL COMMENT 'material id',
  `parse_task_id` bigint NOT NULL COMMENT 'parse task id',
  `course_id` bigint DEFAULT NULL COMMENT 'course id',
  `knowledge_point_id` bigint DEFAULT NULL COMMENT 'knowledge point id',
  `knowledge_point_name` varchar(300) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'knowledge point name',
  `ideology_element` varchar(300) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'ideology element',
  `evidence_snippet` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'evidence snippet',
  `match_reason` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'match reason',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'created time',
  PRIMARY KEY (`id`),
  KEY `idx_tmt_material` (`material_id`),
  KEY `idx_tmt_task` (`parse_task_id`),
  KEY `idx_tmt_course` (`course_id`),
  KEY `idx_tmt_knowledge_name` (`knowledge_point_name`),
  KEY `idx_tmt_ideology` (`ideology_element`)
) ENGINE=InnoDB AUTO_INCREMENT=26 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='teaching material traces';
/*!40101 SET character_set_client = @saved_cs_client */;

