/*!40000 ALTER TABLE `teaching_material_traces` DISABLE KEYS */;
INSERT INTO `teaching_material_traces` VALUES (1,1,4,NULL,NULL,'CDN在高流量下的源站保护角色','责任担当','CDN不只是加速器，更像一个：流量削峰层、缓存治理层、回源控制层、动态请求优化层、可观测性入口层','强调在高流量场景下通过削峰、回源控制和可观测性守护系统稳定，体现面向关键基础设施的工程责任。','2026-04-22 20:58:20'),(2,1,4,NULL,NULL,'CDN在高流量下的源站保护角色','系统观念','CDN不只是加速器，更像一个：流量削峰层、缓存治理层、回源控制层、动态请求优化层、可观测性入口层','将CDN定位为流量削峰层、缓存治理层和观测入口层，体现从整体链路统筹稳定性的系统思维。','2026-04-22 20:58:20'),(3,1,4,NULL,NULL,'静态请求与动态请求的治理差异','实事求是','静态请求…商品图片、JS/CSS…动态请求…登录、查库存、下订单…动态请求无法缓存，但又要低延迟透传','根据静态与动态请求的不同特征采取差异化治理方案，体现从实际问题出发选择技术路径。','2026-04-22 20:58:20'),(4,1,4,NULL,NULL,'静态请求与动态请求的治理差异','精准施策','静态请求…商品图片、JS/CSS…动态请求…登录、查库存、下订单…动态请求无法缓存，但又要低延迟透传','区分缓存减压与链路优化两类手段，反映面向具体业务场景进行精细化治理的意识。','2026-04-22 20:58:20'),(5,1,4,NULL,NULL,'stale-while-revalidate语义','效率意识','stale-while-revalidate允许缓存对象在变成stale后，先返回旧内容，再触发后台刷新','通过先返回旧内容再后台刷新，平衡响应速度与更新效率，体现对服务效率的重视。','2026-04-22 20:58:20'),(6,1,4,NULL,NULL,'stale-while-revalidate语义','辩证思维','stale-while-revalidate允许缓存对象在变成stale后，先返回旧内容，再触发后台刷新','该机制兼顾性能与更新能力，体现对速度与一致性关系的平衡把握。','2026-04-22 20:58:20'),(7,1,4,NULL,NULL,'stale-while-revalidate的时间窗口理解','严谨规范','Cache-Control:public,max-age=60,stale-while-revalidate=30…前60秒：缓存是新鲜的…超过60秒但未超过额外30秒：允许先返回旧缓存','准确区分max-age与stale-while-revalidate的时间边界，体现遵循技术规范和精确认知的要求。','2026-04-22 20:58:20'),(8,1,4,NULL,NULL,'stale-while-revalidate的时间窗口理解','科学精神','Cache-Control:public,max-age=60,stale-while-revalidate=30…前60秒：缓存是新鲜的…超过60秒但未超过额外30秒：允许先返回旧缓存','对缓存生命周期进行明确、可验证的时间划分，体现基于规则和证据理解机制。','2026-04-22 20:58:20'),(9,1,4,NULL,NULL,'stale-while-revalidate的适用边界','底线意识','高频访问的列表页…更新不是秒级强一致的内容…坑1：以为它适合所有动态页面…把有强一致要求的数据也做了陈旧返回','明确其不适用于库存和价格等强一致数据，体现对业务正确性底线的坚守。','2026-04-22 20:58:20'),(10,1,4,NULL,NULL,'stale-while-revalidate的适用边界','风险意识','高频访问的列表页…更新不是秒级强一致的内容…坑1：以为它适合所有动态页面…把有强一致要求的数据也做了陈旧返回','强调错误使用陈旧返回会带来一致性风险，体现前置识别和防范风险的意识。','2026-04-22 20:58:20'),(11,1,4,NULL,NULL,'缓存穿透','安全意识','穿透：查的是根本不存在的数据…防法：对不存在结果做短TTL空值缓存、参数合法性校验、布隆过滤器或存在性过滤','通过参数校验、布隆过滤器等方式阻断异常请求，体现对系统安全与防护的重视。','2026-04-22 20:58:20'),(12,1,4,NULL,NULL,'缓存穿透','预防为主','穿透：查的是根本不存在的数据…防法：对不存在结果做短TTL空值缓存、参数合法性校验、布隆过滤器或存在性过滤','空值缓存和存在性过滤属于前置防护手段，体现主动预防问题扩散的思路。','2026-04-22 20:58:20'),(13,1,4,NULL,NULL,'缓存击穿','风险意识','击穿：某个热点数据刚好失效，大量请求同时打后端…防法：热点预热、互斥锁/singleflight、逻辑过期+异步刷新','针对热点失效瞬间的大并发回源风险设计互斥锁和异步刷新，体现对突发风险的识别与控制。','2026-04-22 20:58:20'),(14,1,4,NULL,NULL,'缓存击穿','未雨绸缪','击穿：某个热点数据刚好失效，大量请求同时打后端…防法：热点预热、互斥锁/singleflight、逻辑过期+异步刷新','热点预热等手段强调在高峰到来前做好准备，体现超前防范意识。','2026-04-22 20:58:20'),(15,1,4,NULL,NULL,'缓存雪崩','底线思维','雪崩：大量缓存同时失效，像闸门一起打开…防法：TTL加随机抖动、分批发布与预热、多级缓存、限流与降级','围绕大面积失效导致后端被压垮的极端场景进行治理，体现守住系统稳定底线的思维。','2026-04-22 20:58:20'),(16,1,4,NULL,NULL,'缓存雪崩','系统观念','雪崩：大量缓存同时失效，像闸门一起打开…防法：TTL加随机抖动、分批发布与预热、多级缓存、限流与降级','通过随机抖动、多级缓存、限流降级等多层手段协同治理，体现全局性系统治理思维。','2026-04-22 20:58:20'),(17,1,4,NULL,NULL,'精准缓存刷新与预热','精细管理','缓存刷新是把旧内容从缓存体系里剔除，缓存预热是提前把即将被访问的内容放进缓存体系','刷新与预热分别面向一致性和冷启动问题，体现对资源和策略进行精细化管理。','2026-04-22 20:58:20'),(18,1,4,NULL,NULL,'精准缓存刷新与预热','质量意识','缓存刷新是把旧内容从缓存体系里剔除，缓存预热是提前把即将被访问的内容放进缓存体系','通过精准刷新减少旧内容，通过预热降低首波回源，体现保障服务质量与用户体验的意识。','2026-04-22 20:58:20'),(19,1,4,NULL,NULL,'避免全站一键清缓存','审慎用权','不做全站大面积清缓存，避免瞬时雪崩…一刷新就全站抖动…根因：刷新粒度过粗，误删大量健康缓存','强调不能粗放式全站清缓存，体现对高影响操作保持克制和审慎。','2026-04-22 20:58:20'),(20,1,4,NULL,NULL,'避免全站一键清缓存','风险意识','不做全站大面积清缓存，避免瞬时雪崩…一刷新就全站抖动…根因：刷新粒度过粗，误删大量健康缓存','认识到粗粒度刷新会引发命中率骤降和回源洪峰，体现对操作风险的敬畏。','2026-04-22 20:58:20'),(21,1,4,NULL,NULL,'DCDN的核心原理','创新意识','动态加速不是靠缓存命中，而是靠优化请求在网络中的路径、协议与传输方式，让动态请求更快、更稳地到达源站','通过路径优选、协议优化和链路调优提升动态请求性能，体现以技术创新解决复杂问题。','2026-04-22 20:58:20'),(22,1,4,NULL,NULL,'DCDN的核心原理','系统观念','动态加速不是靠缓存命中，而是靠优化请求在网络中的路径、协议与传输方式，让动态请求更快、更稳地到达源站','从边缘接入到骨干网再到源站整体优化传输链路，体现面向全链路的系统思维。','2026-04-22 20:58:20'),(23,1,4,NULL,NULL,'动态加速与内容缓存的区别','求真务实','这里的收益不来自“少一次回源”…坑1：把动态加速理解成“接口也能缓存”…根因：混淆“网络加速”和“内容缓存”','明确动态加速不等于接口缓存，强调按技术本质理解方案，避免概念混淆。','2026-04-22 20:58:20'),(24,1,4,NULL,NULL,'动态加速与内容缓存的区别','规范意识','这里的收益不来自“少一次回源”…坑1：把动态加速理解成“接口也能缓存”…根因：混淆“网络加速”和“内容缓存”','提醒误配缓存规则可能造成错误缓存下单和个性化结果，体现遵循规则与边界的重要性。','2026-04-22 20:58:20'),(25,1,4,NULL,NULL,'动态加速与内容缓存的区别','责任担当','这里的收益不来自“少一次回源”…坑1：把动态加速理解成“接口也能缓存”…根因：混淆“网络加速”和“内容缓存”','对动态业务结果的正确性负责，防止错误缓存影响交易和用户权益，体现工程责任。','2026-04-22 20:58:20');
/*!40000 ALTER TABLE `teaching_material_traces` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `teaching_materials`
--

DROP TABLE IF EXISTS `teaching_materials`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `teaching_materials` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'material id',
  `parse_task_id` bigint NOT NULL COMMENT 'related parse task id',
  `user_id` bigint NOT NULL COMMENT 'teacher user id',
  `title` varchar(300) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'material title',
  `lecture_notes` text COLLATE utf8mb4_unicode_ci COMMENT 'editable lecture notes',
  `cases_json` json DEFAULT NULL COMMENT 'editable cases in json array',
  `questions_json` json DEFAULT NULL COMMENT 'editable questions in json array',
  `document_structure_json` json DEFAULT NULL COMMENT 'snapshot of document structure json',
  `knowledge_points_json` json DEFAULT NULL COMMENT 'snapshot of knowledge points json',
  `ideology_matches_json` json DEFAULT NULL COMMENT 'snapshot of ideology match json',
  `trace_json` json DEFAULT NULL COMMENT 'trace information json',
  `schema_version` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT 'v1' COMMENT 'pipeline schema version',
  `version_no` int NOT NULL DEFAULT '1' COMMENT 'material version number',
  `is_latest` tinyint NOT NULL DEFAULT '1' COMMENT 'latest flag 1 yes 0 no',
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'DRAFT' COMMENT 'DRAFT or PUBLISHED',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'created time',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT 'updated time',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT 'soft delete flag',
  `course_id` bigint DEFAULT NULL COMMENT 'optional course binding id',
  PRIMARY KEY (`id`),
  KEY `idx_tm_task_latest` (`parse_task_id`,`is_latest`),
  KEY `idx_tm_task_version` (`parse_task_id`,`version_no`),
  KEY `idx_tm_user` (`user_id`),
  KEY `idx_tm_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='teaching materials table';
/*!40101 SET character_set_client = @saved_cs_client */;

